function validate([arr, k]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return 'arr needs 1 to 1000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value of arr is a whole number from 1 to 1000.';
  for (let i = 1; i < arr.length; i++) if (arr[i - 1] >= arr[i]) return 'arr must be strictly increasing.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is a whole number from 1 to 1000.';
  return null;
}

