function findKthPositive(arr, k) {
  let left = 0;
  let right = arr.length;

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    const missing = arr[mid] - (mid + 1);
    if (missing < k) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return left + k;
}

