function findKthPositive(arr, k) {
  // Walk the positive integers one by one and count the absent ones.
  const present = new Set(arr);
  let count = 0;
  for (let value = 1; ; value++) {
    if (present.has(value)) continue;
    count++;
    if (count === k) return value;
  }
}

