function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const top = size === 'large' ? 1000 : 4 + pick(17);
  const keep = size === 'large' ? 0.3 + rand() * 0.7 : rand();
  // Keep each value of 1..top with probability keep; the result is strictly increasing.
  let arr = [];
  for (let value = 1; value <= top; value++) if (rand() < keep) arr.push(value);
  if (arr.length === 0) arr = [1 + pick(top)];
  const k = size === 'large' ? 1 + pick(1000) : 1 + pick(top + 3);
  return [arr, k];
}
